import re

_SKU_RE = re.compile(r"([A-Z]{2,4})-(\d{4})-([A-Z])")


def bulk_discount(qty):
    """Return the discount rate for an integer quantity."""
    if qty >= 100:
        return 0.15
    if qty >= 20:
        return 0.05
    return 0.0


def line_total(unit_price, qty):
    """Return unit_price * qty with the bulk discount applied, rounded to 2 places."""
    return round(unit_price * qty * (1 - bulk_discount(qty)), 2)


def parse_sku(s):
    """Parse a SKU of the form CAT-1234-X into its parts.

    Raises ValueError if the input does not match the expected format.
    """
    if not isinstance(s, str):
        raise ValueError(f"invalid SKU: {s!r}")
    m = _SKU_RE.fullmatch(s)
    if m is None:
        raise ValueError(f"invalid SKU: {s!r}")
    category, number, variant = m.groups()
    return {"category": category, "number": int(number), "variant": variant}

def shipping_zone(country_code):
    if country_code == "US":
        return 1
    if country_code in ("CA", "MX"):
        return 2
    return 3


def shipping_cost(weight_kg, zone):
    base = {1: 5.0, 2: 12.0, 3: 25.0}[zone]
    return round(base + 0.8 * weight_kg, 2)


def is_oversize(l, w, h):
    return max(l, w, h) > 120 or (l + w + h) > 300

